<?php if($allocation['status']==='draft'):?><details class="allocation-tool" id="move-student"><summary><span>Move a student<small>Correct an assigned seat</small></span></summary><div class="allocation-tool-body"><div class="form-section-heading"><p class="eyebrow">Manual correction</p><h2>Move an assigned student</h2><p>Every correction is marked as a manual override and written to the audit trail.</p></div><form class="form-grid three" method="post" action="<?= e(url('seating/'.$allocation['id'].'/move')) ?>"><?= csrf_field() ?><label>Current assignment<select name="assignment_id" required><option value="">Select student</option><?php foreach($assignments as $item):?><option value="<?= (int)$item['id'] ?>" data-school="<?= (int)$item['school_id'] ?>" data-group="<?= e($item['group_key']) ?>"><?= e($item['roll_no_original'].' - '.$item['room_code'].'/'.$item['seat_label']) ?></option><?php endforeach;?></select></label><label>New vacant seat<select name="seat_id" required><option value="">Select seat</option><?php foreach($availableSeats as $seat):?><option data-school="<?= (int)$seat['school_id'] ?>" data-group="<?= e($seat['group_key']) ?>" value="<?= (int)$seat['id'] ?>"><?= e($seat['room_code'].' / '.$seat['seat_label']) ?></option><?php endforeach;?></select></label><label>Reason<input name="reason" required placeholder="Operational correction"><button class="secondary-button">Move student</button></label></form></div></details><?php endif;?>
<?php if(($document['rules']['mode']??'')==='paired_cohorts'):?><details class="allocation-tool" id="saved-pairs"><summary><span>Pairing rules<small>Review saved branch and batch pairs</small></span></summary><div class="allocation-tool-body pairing-rules-summary"><?php foreach($document['rules']['pairings'] as $pair):?><p><strong><?= e($document['rules']['cohorts'][$pair['left']]['label']) ?></strong> <?php if(!empty($pair['single_remaining'])):?><?= !empty($pair['empty_partner'])?' · alternate columns / empty partner':' · final remaining branch' ?><?php else:?>with <strong><?= e($document['rules']['cohorts'][$pair['right']]['label']) ?></strong><?php endif;?></p><?php endforeach;?></div></details><?php endif;?>
<details class="allocation-tool"><summary><span>Validation details<small><?= $validation['valid']?'All allocation checks passed':'Review the checks below' ?></small></span></summary><div class="allocation-tool-body"><dl class="allocation-validation-list"><?php foreach($validation as $name=>$value):if($name==='valid')continue;?><div><dt><?= e(ucfirst(str_replace('_',' ',$name))) ?></dt><dd><?= (int)$value ?></dd></div><?php endforeach;?></dl></div></details>
</div></section></div>
